on":"The time expression 'yesterday' calls for 'completed'.","difficulty":"hard","source":"past-paper-style","usage_type":"past_paper"},{"external_id":"FAST-0994","subject":"English","subject_slug":"english","chapter_slug":"prepositions","chapter_title":"Prepositions","statement":"Choose the correct preposition: They are interested ___ solving the problem.","chapter_num":3,"node_kind":"topic","option_a":"in","option_b":"with","option_c":"by","option_d":"at","correct_option":"a","explanation":"The standard expression requires the preposition 'in'.","difficulty":"medium","source":"past-paper-style","usage_type":"past_paper"},{"external_id":"FAST-0995","subject":"English","subject_slug":"english","chapter_slug":"sentence-correction","chapter_title":"Sentence Correction","statement":"Choose the grammatically correct sentence for set 21.","chapter_num":4,"node_kind":"topic","option_a":"He does not know a the answer.","option_b":"He does not know the answer yesterday yesterday.","option_c":"He does not know the answer.","option_d":"He do not know the answer.","correct_option":"c","explanation":"'He does not know the answer.' has correct agreement, tense, and word order.","difficulty":"easy","source":"practice","usage_type":"practice"},{"external_id":"FAST-0996","subject":"English","subject_slug":"english","chapter_slug":"synonyms","chapter_title":"Synonyms","statement":"Choose the closest synonym of 'abundant' in ordinary academic usage.","chapter_num":5,"node_kind":"topic","option_a":"scarce","option_b":"uncertain","option_c":"plentiful","option_d":"hostile","correct_option":"c","explanation":"'plentiful' most nearly matches the meaning of 'abundant'.","difficulty":"medium","source":"past-paper-style","usage_type":"past_paper"},{"external_id":"FAST-0997","subject":"English","subject_slug":"english","chapter_slug":"antonyms","chapter_title":"Antonyms","statement":"Choose the antonym of 'expand' in ordinary academic usage.","chapter_num":6,"node_kind":"topic","option_a":"contract","option_b":"similar","option_c":"careful","option_d":"steady","correct_option":"a","explanation":"'contract' expresses the opposite of 'expand'.","difficulty":"medium","source":"past-paper-style","usage_type":"past_paper"},{"external_id":"FAST-0998","subject":"English","subject_slug":"english","chapter_slug":"contextual-vocabulary","chapter_title":"Contextual Vocabulary","statement":"In the sentence 'Although the route was difficult, the hikers remained resolute.' what does 'resolute' most nearly mean?","chapter_num":7,"node_kind":"topic","option_a":"lengthy","option_b":"optional","option_c":"careless","option_d":"determined","correct_option":"d","explanation":"Context shows that 'resolute' means 'determined'.","difficulty":"easy","source":"practice","usage_type":"practice"},{"external_id":"FAST-0999","subject":"English","subject_slug":"english","chapter_slug":"reading-comprehension","chapter_title":"Reading Comprehension","statement":"Read the sentence: Solar panels generate electricity without burning fuel, but their output varies with sunlight. Which statement best captures its main idea?","chapter_num":8,"node_kind":"topic","option_a":"The author gives no information.","option_b":"Only one detail matters.","option_c":"The sentence rejects all technology.","option_d":"Their output depends on sunlight.","correct_option":"d","explanation":"The correct choice restates the central claim without adding or contradicting details.","difficulty":"medium","source":"practice","usage_type":"practice"},{"external_id":"FAST-1000","subject":"English","subject_slug":"english","chapter_slug":"subject-verb-agreement","chapter_title":"Subject Verb Agreement","statement":"Complete the sentence: The committee, along with its chair, ___ meeting today.","chapter_num":1,"node_kind":"topic","option_a":"is","option_b":"were","option_c":"have","option_d":"are","correct_option":"a","explanation":"The controlling subject is singular, so 'is' is required.","difficulty":"easy","source":"practice","usage_type":"practice"}]$fast_questions$::jsonb) as row_data(
  external_id text,
  subject text,
  subject_slug text,
  chapter_num integer,
  chapter_slug text,
  chapter_title text,
  node_kind text,
  statement text,
  option_a text,
  option_b text,
  option_c text,
  option_d text,
  correct_option text,
  explanation text,
  difficulty text,
  source text,
  usage_type text
);

insert into topics (
  external_id, subject_id, kind, title, slug, display_order, deleted_at
)
select distinct on (stage.subject_slug, stage.chapter_slug)
  'fast-' || stage.subject_slug || '-' || stage.chapter_slug,
  subject.id,
  stage.node_kind::topic_kind,
  stage.chapter_title,
  stage.chapter_slug,
  stage.chapter_num,
  null
from fast_import_stage stage
join subjects subject on subject.slug = stage.subject_slug
order by stage.subject_slug, stage.chapter_slug, stage.chapter_num
on conflict (external_id) do update set
  subject_id = excluded.subject_id,
  kind = excluded.kind,
  title = excluded.title,
  slug = excluded.slug,
  display_order = excluded.display_order,
  deleted_at = null;

insert into questions (
  external_id, subject_id, topic_id, difficulty, statement,
  explanation, source, moderation_status, review_note, deleted_at
)
select
  stage.external_id,
  subject.id,
  topic.id,
  stage.difficulty::difficulty,
  stage.statement,
  stage.explanation,
  stage.source,
  'approved'::moderation_status,
  null,
  null
from fast_import_stage stage
join subjects subject on subject.slug = stage.subject_slug
join topics topic
  on topic.external_id = 'fast-' || stage.subject_slug || '-' || stage.chapter_slug
on conflict (external_id) do update set
  subject_id = excluded.subject_id,
  topic_id = excluded.topic_id,
  difficulty = excluded.difficulty,
  statement = excluded.statement,
  explanation = excluded.explanation,
  source = excluded.source,
  moderation_status = excluded.moderation_status,
  review_note = null,
  deleted_at = null;

update question_options option_row
set is_correct = false
from questions question
join fast_import_stage stage on stage.external_id = question.external_id
where option_row.question_id = question.id;

delete from question_options option_row
using questions question, fast_import_stage stage
where option_row.question_id = question.id
  and question.external_id = stage.external_id
  and option_row.option_label not in ('a', 'b', 'c', 'd');

insert into question_options (
  question_id, option_label, content, is_correct, display_order
)
select
  question.id,
  option_data.label,
  option_data.content,
  option_data.label = stage.correct_option,
  option_data.ord
from fast_import_stage stage
join questions question on question.external_id = stage.external_id
cross join lateral (values
  ('a', stage.option_a, 0),
  ('b', stage.option_b, 1),
  ('c', stage.option_c, 2),
  ('d', stage.option_d, 3)
) as option_data(label, content, ord)
on conflict (question_id, option_label) do update set
  content = excluded.content,
  is_correct = excluded.is_correct,
  display_order = excluded.display_order;

insert into question_tests (
  question_id, entry_test_id, usage_type, difficulty, paper_session
)
select
  question.id,
  test.id,
  stage.usage_type::question_usage,
  stage.difficulty::difficulty,
  case when stage.usage_type = 'past_paper' then 'Past-paper style' else null end
from fast_import_stage stage
join questions question on question.external_id = stage.external_id
cross join entry_tests test
where test.slug = 'fast'
on conflict (question_id, entry_test_id) do update set
  usage_type = excluded.usage_type,
  difficulty = excluded.difficulty,
  source_year = null,
  paper_session = excluded.paper_session;

do $$
declare
  imported_count integer;
  topic_count integer;
  past_paper_count integer;
  practice_count integer;
  invalid_question_count integer;
begin
  select
    count(*),
    count(*) filter (where link.usage_type = 'past_paper'),
    count(*) filter (where link.usage_type = 'practice')
  into imported_count, past_paper_count, practice_count
  from question_tests link
  join entry_tests test on test.id = link.entry_test_id
  join questions question on question.id = link.question_id
  where test.slug = 'fast' and question.external_id like 'FAST-%';

  select count(distinct question.topic_id) into topic_count
  from question_tests link
  join entry_tests test on test.id = link.entry_test_id
  join questions question on question.id = link.question_id
  where test.slug = 'fast' and question.external_id like 'FAST-%';

  select count(*) into invalid_question_count
  from (
    select question.id
    from fast_import_stage stage
    join questions question on question.external_id = stage.external_id
    join question_options option_row on option_row.question_id = question.id
    group by question.id
    having count(*) <> 4
       or count(*) filter (where option_row.is_correct) <> 1
  ) invalid;

  if imported_count <> 1000 or topic_count <> 45 then
    raise exception 'FAST import expected 1000 questions/45 topics, found %/%',
      imported_count, topic_count;
  end if;
  if past_paper_count <> 394 or practice_count <> 606 then
    raise exception 'FAST usage split expected 394/606, found %/%',
      past_paper_count, practice_count;
  end if;
  if invalid_question_count <> 0 then
    raise exception 'FAST import found % questions with invalid options/answer keys',
      invalid_question_count;
  end if;
end $$;

commit;
